cases.bad:
// coarse URL guard — one fire per page, blocks catch-up
autoDownloadedTabs: Map<tabId, url>;
if (state.url === tabUrl) return; // subtitles never enqueued

cases.good:
// id-level dedup — re-run allowed, skip already-enqueued
autoDownloadedTabs: Map<tabId, { url, enqueuedIds: Set<string> }>;
const newIds = await tryAutoDownload(media, state.enqueuedIds);
newIds.forEach(id => state.enqueuedIds.add(id));

// fresh page load = new state
if (!state || state.url !== tabUrl) {
  const newIds = await tryAutoDownload(media);
  state = { url: tabUrl, enqueuedIds: new Set(newIds) };
}
